<script>
(() => { const shell=document.querySelector('[data-mc-shell]'); if(!shell)return; const sidebar=shell.querySelector('[data-mc-sidebar]'); const overlay=shell.querySelector('[data-mc-overlay]'); const mobile=shell.querySelector('[data-mc-mobile-toggle]'); const mobileView=()=>window.matchMedia('(max-width: 800px)').matches; const close=()=>{sidebar?.classList.remove('is-open');overlay?.classList.remove('is-visible');document.body.classList.remove('mc-drawer-open')}; mobile?.addEventListener('click',()=>{sidebar?.classList.add('is-open');overlay?.classList.add('is-visible');document.body.classList.add('mc-drawer-open')}); overlay?.addEventListener('click',close); sidebar?.querySelectorAll('a').forEach(link=>link.addEventListener('click',()=>{if(mobileView())close()})); window.addEventListener('resize',()=>{if(!mobileView())close()}); document.addEventListener('keydown',event=>{if(event.key==='Escape')close()}); })();
</script>
<script>
(() => { const toggle=document.querySelector('[data-mc-notification-toggle]'); const popover=document.querySelector('[data-mc-notification-popover]'); if(!toggle||!popover)return; const close=()=>{popover.hidden=true;toggle.setAttribute('aria-expanded','false')}; toggle.addEventListener('click',event=>{event.stopPropagation();const open=popover.hidden;popover.hidden=!open;toggle.setAttribute('aria-expanded',open?'true':'false')}); document.addEventListener('click',event=>{if(!popover.contains(event.target)&&!toggle.contains(event.target))close()}); document.addEventListener('keydown',event=>{if(event.key==='Escape')close()}); })();
</script>
<script>
(() => {
    const shell = document.querySelector('[data-mc-shell]');
    if (!shell) return;
    const groups = [...shell.querySelectorAll('[data-mc-accordion]')];
    groups.forEach(group => group.querySelector('.mc-side-button')?.addEventListener('click', () => {
        const wasOpen = group.classList.contains('is-open');
        groups.forEach(other => {
            other.classList.remove('is-open');
            other.querySelector('.mc-side-button')?.setAttribute('aria-expanded', 'false');
            const submenu = other.querySelector('.mc-subnav');
            if (submenu) submenu.hidden = true;
        });
        if (!wasOpen) {
            group.classList.add('is-open');
            group.querySelector('.mc-side-button')?.setAttribute('aria-expanded', 'true');
            const submenu = group.querySelector('.mc-subnav');
            if (submenu) submenu.hidden = false;
        }
    }));

    const profileToggle = shell.querySelector('[data-mc-profile-toggle]');
    const profileMenu = shell.querySelector('[data-mc-profile-menu]');
    const closeProfile = () => { if (profileMenu) profileMenu.hidden = true; profileToggle?.setAttribute('aria-expanded', 'false'); };
    profileToggle?.addEventListener('click', event => {
        event.stopPropagation();
        const open = profileMenu?.hidden ?? true;
        if (profileMenu) profileMenu.hidden = !open;
        profileToggle.setAttribute('aria-expanded', open ? 'true' : 'false');
    });
    document.addEventListener('click', event => { if (profileMenu && !profileMenu.contains(event.target) && !profileToggle?.contains(event.target)) closeProfile(); });
    document.addEventListener('keydown', event => { if (event.key === 'Escape') closeProfile(); });
})();
</script>
@endpush
